S, P, D = "shloka", "pad", "doha"

_G = "\nगतिस्त्वं गतिस्त्वं त्वमेका भवानि॥"
BHAVANI_ASHTAKAM = [
 (S,"न तातो न माता न बन्धुर्न दाता\nन पुत्रो न पुत्री न भृत्यो न भर्ता।\nन जाया न विद्या न वृत्तिर्ममैव" + _G,
  "हे भवानी, न पिता, न माता, न भाई, न कोई देने वाला; न बेटा, न बेटी, न सेवक, न स्वामी; न पत्नी, न विद्या, न रोज़गार — इनमें से कोई भी सच में मेरा नहीं। मेरी गति, मेरा सहारा केवल आप हैं, केवल आप।"),
 (S,"भवाब्धावपारे महादुःखभीरु\nपपात प्रकामी प्रलोभी प्रमत्तः।\nकुसंसारपाशप्रबद्धः सदाहं" + _G,
  "मैं इस अपार संसार-सागर में गिरा पड़ा हूँ, बड़े दुखों से डरता हूँ; कामनाओं, लालच और लापरवाही से भरा हूँ और बुरे संसार के जाल में सदा बँधा रहता हूँ। हे भवानी, मेरा सहारा केवल आप हैं।"),
 (S,"न जानामि दानं न च ध्यानयोगं\nन जानामि तन्त्रं न च स्तोत्रमन्त्रम्।\nन जानामि पूजां न च न्यासयोगं" + _G,
  "मैं न दान जानता हूँ, न ध्यान-योग; न तंत्र जानता हूँ, न स्तोत्र और मंत्र; न पूजा की विधि जानता हूँ, न न्यास। हे भवानी, फिर भी मेरी गति केवल आप हैं।"),
 (S,"न जानामि पुण्यं न जानामि तीर्थं\nन जानामि मुक्तिं लयं वा कदाचित्।\nन जानामि भक्तिं व्रतं वापि मात-" + _G.replace("\n","\nर्"),
  "मैं न पुण्य जानता हूँ, न तीर्थ; न मुक्ति जानता हूँ, न ईश्वर में लीन होना; हे माँ, न भक्ति जानता हूँ, न व्रत। मेरा सहारा केवल आप हैं।"),
 (S,"कुकर्मी कुसङ्गी कुबुद्धिः कुदासः\nकुलाचारहीनः कदाचारलीनः।\nकुदृष्टिः कुवाक्यप्रबन्धः सदाहं" + _G,
  "मैं बुरे काम करने वाला, बुरी संगत वाला, बुरी बुद्धि वाला और बुरा सेवक हूँ; कुल की मर्यादा से हीन, बुरे आचरण में डूबा, बुरी नज़र और कड़वे बोल वाला हूँ। ऐसे मुझ पर भी — हे भवानी, आप ही मेरा सहारा हैं।"),
 (S,"प्रजेशं रमेशं महेशं सुरेशं\nदिनेशं निशीथेश्वरं वा कदाचित्।\nन जानामि चान्यत् सदाहं शरण्ये" + _G,
  "ब्रह्मा, विष्णु, शिव, इंद्र, सूर्य या चंद्रमा — मैं किसी और को कभी नहीं जानता। हे शरण देने वाली माँ, मेरी गति सदा केवल आप हैं।"),
 (S,"विवादे विषादे प्रमादे प्रवासे\nजले चानले पर्वते शत्रुमध्ये।\nअरण्ये शरण्ये सदा मां प्रपाहि" + _G,
  "झगड़े में, दुख में, भूल में, परदेस में; पानी में, आग में, पहाड़ पर, शत्रुओं के बीच और जंगल में — हे शरण देने वाली, सदा मेरी रक्षा कीजिए। मेरा सहारा केवल आप हैं।"),
 (S,"अनाथो दरिद्रो जरारोगयुक्तो\nमहाक्षीणदीनः सदा जाड्यवक्त्रः।\nविपत्तौ प्रविष्टः प्रणष्टः सदाहं" + _G,
  "मैं अनाथ हूँ, गरीब हूँ, बुढ़ापे और रोग से घिरा हूँ; बहुत कमज़ोर और दीन हूँ, मेरे मुँह से बात तक ठीक नहीं निकलती; विपत्ति में फँसा, पूरी तरह टूटा हुआ हूँ। हे भवानी, मेरी गति केवल आप हैं।"),
 (P,"इति श्रीमच्छङ्कराचार्यकृतं भवान्यष्टकं सम्पूर्णम्।","इस प्रकार श्री आदि शंकराचार्य द्वारा रचित भवानी अष्टक पूरा हुआ।"),
]

HANUMAN_STAVAN = [
 (D,"प्रनवउँ पवनकुमार खल बन पावक ग्यानघन।\nजासु हृदय आगार बसहिं राम सर चाप धर॥",
  "मैं पवनपुत्र हनुमान को प्रणाम करता हूँ, जो दुष्टों के वन को जलाने वाली आग जैसे और ज्ञान से भरे हैं; जिनके हृदय रूपी घर में धनुष-बाण धारी श्रीराम निवास करते हैं। (रामचरितमानस, बालकांड)"),
 (S,"अतुलितबलधामं हेमशैलाभदेहं\nदनुजवनकृशानुं ज्ञानिनामग्रगण्यम्।\nसकलगुणनिधानं वानराणामधीशं\nरघुपतिप्रियभक्तं वातजातं नमामि॥",
  "अतुलनीय बल के धाम, सोने के पर्वत जैसे शरीर वाले, राक्षसों के वन के लिए अग्नि, ज्ञानियों में सबसे आगे, सब गुणों के भंडार, वानरों के स्वामी, श्रीराम के प्रिय भक्त पवनपुत्र को मैं नमस्कार करता हूँ। (रामचरितमानस, सुंदरकांड)"),
 (S,"गोष्पदीकृतवारीशं मशकीकृतराक्षसम्।\nरामायणमहामालारत्नं वन्देऽनिलात्मजम्॥",
  "जिन्होंने समुद्र को गाय के खुर के गड्ढे जितना छोटा बना दिया और राक्षसों को मच्छर जैसा तुच्छ कर दिया, जो रामायण रूपी महामाला के रत्न हैं — उन पवनपुत्र की मैं वंदना करता हूँ।"),
 (S,"अञ्जनानन्दनं वीरं जानकीशोकनाशनम्।\nकपीशमक्षहन्तारं वन्दे लङ्काभयङ्करम्॥",
  "अंजनी के पुत्र, वीर, सीता माता का शोक मिटाने वाले, वानरों के स्वामी, रावण-पुत्र अक्षकुमार को मारने वाले और लंका को भयभीत करने वाले हनुमान की मैं वंदना करता हूँ।"),
 (S,"उल्लङ्घ्य सिन्धोः सलिलं सलीलं\nयः शोकवह्निं जनकात्मजायाः।\nआदाय तेनैव ददाह लङ्कां\nनमामि तं प्राञ्जलिराञ्जनेयम्॥",
  "जिन्होंने खेल-खेल में समुद्र का जल लाँघ लिया, और सीता माता के शोक की आग लेकर उसी से लंका जला दी — उन अंजनी-नंदन को मैं हाथ जोड़कर नमस्कार करता हूँ।"),
 (S,"मनोजवं मारुततुल्यवेगं\nजितेन्द्रियं बुद्धिमतां वरिष्ठम्।\nवातात्मजं वानरयूथमुख्यं\nश्रीरामदूतं शरणं प्रपद्ये॥",
  "मन जैसी गति और हवा जैसे वेग वाले, इंद्रियों को जीतने वाले, बुद्धिमानों में श्रेष्ठ, पवन-पुत्र, वानर-सेना के प्रमुख श्रीराम-दूत की मैं शरण लेता हूँ।"),
 (S,"आञ्जनेयमतिपाटलाननं\nकाञ्चनाद्रिकमनीयविग्रहम्।\nपारिजाततरुमूलवासिनं\nभावयामि पवमाननन्दनम्॥",
  "गहरे लाल मुख वाले, सोने के पर्वत जैसे सुंदर शरीर वाले, पारिजात वृक्ष की जड़ में निवास करने वाले अंजनी-पुत्र, पवन-नंदन का मैं ध्यान करता हूँ।"),
 (S,"यत्र यत्र रघुनाथकीर्तनं\nतत्र तत्र कृतमस्तकाञ्जलिम्।\nबाष्पवारिपरिपूर्णलोचनं\nमारुतिं नमत राक्षसान्तकम्॥",
  "जहाँ-जहाँ श्रीराम का कीर्तन होता है, वहाँ-वहाँ सिर पर हाथ जोड़े, आँखों में प्रेम के आँसू भरे हनुमान जी मौजूद रहते हैं — राक्षसों का अंत करने वाले उन मारुति को नमस्कार करो।"),
]

VINDHYESHWARI_AARTI = [
 (P,"सुन मेरी देवी पर्वतवासनी, कोई तेरा पार न पाया।\nपान सुपारी ध्वजा नारियल, ले तेरी भेंट चढ़ाया॥",
  "हे पर्वत पर रहने वाली देवी, मेरी विनती सुनो — आपकी महिमा का पार कोई नहीं पा सका। पान, सुपारी, ध्वजा और नारियल लेकर मैंने आपको भेंट चढ़ाई है।"),
 (P,"सुवा चोली तेरे अंग विराजे, केसर तिलक लगाया।\nनंगे पग माँ अकबर आया, सोने का छत्र चढ़ाया॥",
  "आपके अंग पर हरी (तोते के रंग की) चोली शोभा देती है और माथे पर केसर का तिलक है। लोककथा है कि बादशाह अकबर भी नंगे पाँव आपके दरबार आया और सोने का छत्र चढ़ाया।"),
 (P,"ऊँचे पर्वत बन्यो देवालय, नीचे शहर बसाया।\nसतयुग द्वापर त्रेता मध्ये, कलियुग राज सवाया॥",
  "ऊँचे पर्वत पर आपका मंदिर बना है और नीचे नगर बसा है। सतयुग, त्रेता और द्वापर में भी आपकी महिमा थी, और कलियुग में आपका राज सवाया (और भी बढ़कर) है।"),
 (P,"धूप दीप नैवेद्य आरती, मोहन भोग लगाया।\nध्यानू भगत मैया तेरे गुण गाया, मनवांछित फल पाया॥",
  "धूप, दीप, नैवेद्य और आरती के साथ मीठा भोग लगाया है। माँ, भक्त ध्यानू ने आपके गुण गाए और मनचाहा फल पाया।"),
 (P,"सुन मेरी देवी पर्वतवासनी, कोई तेरा पार न पाया॥","आरती का समापन फिर से पहली पंक्ति से — हे पर्वतवासिनी माँ, आपकी महिमा अपार है।"),
]

SHENDUR_LAL_AARTI = [
 (P,"शेंदुर लाल चढ़ायो अच्छा गजमुखको।\nदोंदिल लाल बिराजे सुत गौरीहरको।\nहाथ लिए गुड़लड्डू साँई सुरवरको।\nमहिमा कहे न जाय लागत हूँ पदको॥",
  "हाथी के मुख वाले गणेश जी को सुंदर लाल सिंदूर चढ़ाया गया है। बड़े पेट वाले, लाल रंग में शोभित, गौरी और शिव के पुत्र हाथ में गुड़ के लड्डू लिए हैं — देवताओं में श्रेष्ठ उन स्वामी की महिमा कही नहीं जाती, मैं उनके चरणों में प्रणाम करता हूँ।"),
 (P,"जय देव जय देव, जय जय श्री गणराज।\nविद्या सुखदाता, धन्य तुम्हारो दर्शन, मेरा मन रमता॥",
  "हे देव, हे गणराज, आपकी जय हो! आप विद्या और सुख देने वाले हैं। आपका दर्शन धन्य है — मेरा मन उसी में रम जाता है। (टेक — हर पद के बाद गाई जाती है)"),
 (P,"अष्टौ सिद्धि दासी संकटको बैरी।\nविघ्नविनाशन मंगल मूरत अधिकारी।\nकोटि सूरज प्रकाश ऐसी छबि तेरी।\nगंडस्थल मदमस्तक झूले शशिबिहारी॥",
  "आठों सिद्धियाँ आपकी दासी हैं और आप संकटों के शत्रु हैं। आप विघ्नों का नाश करने वाले, मंगल की मूर्ति और सबके अधिकारी हैं। आपकी छवि करोड़ों सूर्यों जैसी चमकती है; आपके मस्तक पर चंद्रमा शोभा देता है।"),
 (P,"भाव भगत से कोई शरणागत आवे।\nसंतति संपति सबही भरपूर पावे।\nऐसे तुम महाराज मोको अति भावे।\nगोसावीनंदन निशिदिन गुण गावे॥",
  "जो भी भाव और भक्ति से आपकी शरण में आता है, वह संतान, संपत्ति — सब कुछ भरपूर पाता है। हे महाराज, आप मुझे ऐसे ही बहुत प्रिय हैं; गोसावी-नंदन (रचनाकार) दिन-रात आपके गुण गाते हैं।"),
 (P,"जय देव जय देव, जय जय श्री गणराज।\nविद्या सुखदाता, धन्य तुम्हारो दर्शन, मेरा मन रमता॥","आरती का समापन टेक के साथ — हे गणराज, आपकी जय हो।"),
]

_T = "\nओ मैया हम सब उतारें तेरी आरती॥"
AMBE_TU_HAI_JAGDAMBE = [
 (P,"अम्बे तू है जगदम्बे काली, जय दुर्गे खप्पर वाली।\nतेरे ही गुण गाएँ भारती।" + _T,
  "हे माँ अम्बे, आप ही जगदम्बा और काली हैं; खप्पर धारण करने वाली दुर्गा माँ, आपकी जय हो। सारा भारत आपके गुण गाता है — हे मैया, हम सब आपकी आरती उतारते हैं। (टेक)"),
 (P,"तेरे भक्त जनों पर, भीड़ पड़ी है भारी माँ।\nदानव दल पर टूट पड़ो, माँ करके सिंह सवारी॥\nसौ-सौ सिंहों से बलशाली, अष्ट भुजाओं वाली,\nदुष्टों को पल में संहारती।" + _T,
  "माँ, आपके भक्तों पर भारी संकट आ पड़ा है। सिंह पर सवार होकर राक्षसों के दल पर टूट पड़ो। आप सैकड़ों सिंहों से अधिक बलवान और आठ भुजाओं वाली हैं, जो दुष्टों का पल भर में संहार कर देती हैं।"),
 (P,"माँ बेटे का है इस जग में, बड़ा ही निर्मल नाता।\nपूत-कपूत सुने हैं पर ना, माता सुनी कुमाता॥\nसब पे करुणा दरसाने वाली, अमृत बरसाने वाली,\nदुखियों के दुखड़े निवारती।" + _T,
  "इस संसार में माँ और बेटे का रिश्ता सबसे पवित्र है। बेटे के कपूत होने की बात तो सुनी है, पर माता कभी कुमाता नहीं सुनी गई। आप सब पर करुणा दिखाती हैं, अमृत बरसाती हैं और दुखियों के दुख दूर करती हैं।"),
 (P,"नहीं माँगते धन और दौलत, ना चाँदी ना सोना माँ।\nहम तो माँगें माँ तेरे मन में, इक छोटा सा कोना॥\nसबकी बिगड़ी बनाने वाली, लाज बचाने वाली,\nसतियों के सत को सँवारती।" + _T,
  "माँ, हम धन-दौलत, चाँदी या सोना नहीं माँगते — बस आपके मन में एक छोटा-सा कोना चाहते हैं। आप सबकी बिगड़ी बनाती हैं, लाज बचाती हैं और सती-साध्वी स्त्रियों के सत की रक्षा करती हैं।"),
 (P,"चरण शरण में खड़े तुम्हारी, ले पूजा की थाली।\nवरद हस्त सर पर रख दो, माँ संकट हरने वाली॥\nमाँ भर दो भक्ति रस प्याली, अष्ट भुजाओं वाली,\nभक्तों के कारज तू ही सारती।" + _T,
  "पूजा की थाली लेकर हम आपके चरणों की शरण में खड़े हैं। हे संकट हरने वाली माँ, हमारे सिर पर वरदान देने वाला हाथ रख दो। हे आठ भुजाओं वाली, हमारा भक्ति-रस का प्याला भर दो — भक्तों के सारे काम आप ही पूरे करती हैं।"),
]
